// resetForTest clears package state between unit tests.
func resetForTest() {
	launches = avl.Tree{}
	bySymbol = avl.Tree{}
	nextID = 0
	nextTokenID = 0
	var zero address
	protocolAddr = zero
	// padAddr is set in package init - do not clear (realm address is fixed).
	protocolFees = 0
	protocolFeesPaid = 0
	inited = false
	pointsEnabled = false
	testSkipBanker = true // unit tests skip banker; integration/chain tests leave false
	testForceGnoswapList = false
}

package padv17

// Protocol parameters (MVP). Tunable before deploy; post-deploy treated as constants
// unless a future governance path is added with timelock.

const (
	// Token economics
	TotalSupply int64 = 1_000_000_000
	CurveSupply int64 = 800_000_000 // sold on bonding curve
	// PoolSeed is legacy: graduation seeds LP with ALL remaining tokens
	// (TotalSupply - RealSold), not a fixed 200M reserve.
	PoolSeed int64 = 200_000_000

	// Virtual constant-product seed (Pump-style).
	// Max net raise when selling full CurveSupply:
	//   R = VirtualUgnot0 * CurveSupply / (VirtualToken0 - CurveSupply)
	// Source defaults (VU0=30e6, VT0~1.073e9 -> R~87.9e6) suit local tests / 50 GNOT.
	// Sapphire prepare-v13 scales VU0 + keeps VT0 so threshold 10_000 GNOT is reachable
	// before sold-out, with ~P_curve ~ P_pool at graduate (~20% tokens -> LP).
	VirtualUgnot0 int64 = 3_500_000_000    // 30 GNOT virtual (tests)
	VirtualToken0 int64 = 1_073_000_191 // virtual token side

	// Graduation when net ugnot raised into the curve reaches this.
	// Must stay BELOW max raise from exhausting CurveSupply (see Virtual*).
	// Sapphire prepare-v13 patches to 10_000 GNOT and retunes VirtualUgnot0.
	GraduationThreshold int64 = 10_000_000_000

	// Fees: 1.20% total. Of the fee: 40% creator, 40% protocol, 20% LP/k remainder.
	FeeBPS              int64 = 120
	CreatorFeeShareBPS  int64 = 4000
	ProtocolFeeShareBPS int64 = 4000

	// Fallback create bond for unit tests / if bond realm unavailable.
	// Production pad uses createbond.CurrentBondUgnot() (see bond package).
	// Sapphire normal bond = 2 GNOT; promo ~ $20 in ugnot set on bond.StartPromo.
	CreateBondUgnot int64 = 2_000_000
	BondRefundBuyers     int   = 5
	BondRefundMinRaised int64 = 100_000_000 // >=5 GNOT raised
	BondRefundMaxHeights int64 = 100_000

	// Anti-snipe: first N heights, max cumulative tokens per address (BPS of TotalSupply).
	AntiSnipeHeights int64 = 30
	AntiSnipeMaxBuyBPS int64 = 300 // 5% per address in window

	// Status
	StatusCurve     = 0
	StatusGraduated = 1

	// Trade history ring buffer.
	MaxTradeHistory = 128
	// Trade sides stored in history
	TradeSideBuy  = 0
	TradeSideSell = 1
	TradeSideOpen = 2 // initial listing mark

	DenomUgnot = "ugnot"

	// --- Gnoswap auto-list (Sapphire) ---
	// Curve collateral is WUGNOT (Buy TransferFrom). At graduate, pad already holds
	// raised WUGNOT for LP - no realm self-wrap needed.
	// CreatePool fee is fixed in GNS (typically 100e6 = 100 GNS):
	//   Fee = pre-funded GNS on pad OR surplus WUGNOT (fees retained) ExactOut -> GNS
	GnoswapFeeTier     uint32 = 3000 // 0.3% meme tier
	GnoswapTickSpacing int32  = 60
	GnoswapMinTick     int32  = -887272
	GnoswapMaxTick     int32  = 887272
	// Max WUGNOT used as ExactOut maxIn for fee buy (ceiling / slippage).
	// Prefer pre-funding >=100 GNS on pad so LP depth stays = raised.
	GnoswapMaxFeeWugnot int64 = 1_500_000_000 // 1500 GNOT
)

package padv17

import (
	"strconv"
	"strings"

	ammmath "gno.land/p/g1mv0052e7r6s09f5t9xsqf00nj3tqsgt9dg52jr/gnomemepad/ammmathv2"
	"gno.land/p/nt/ufmt/v0"
)

// Render provides on-chain discovery (gnoweb). Read-only by convention.
//
// Paths:
//
//	""              - home / list
//	token/{id}      - launch detail
//	help            - API help
func Render(path string) string {
	path = strings.Trim(path, "/")
	if path == "" {
		return renderHome()
	}
	if path == "help" {
		return renderHelp()
	}
	if strings.HasPrefix(path, "token/") {
		id := strings.TrimPrefix(path, "token/")
		return renderToken(id)
	}
	return "> [!WARNING]\n> Path not found: " + sanitize(path) + "\n"
}

func sanitize(s string) string {
	s = strings.ReplaceAll(s, "`", "'")
	s = strings.ReplaceAll(s, "<", "")
	s = strings.ReplaceAll(s, ">", "")
	return s
}

func renderHome() string {
	out := "# gnomemepad\n\n"
	out += "Meme launchpad - WUGNOT bonding curve -> remaining tokens + raised WUGNOT seed Gnoswap LP (auto-list).\n\n"
	if !inited {
		out += "> [!CAUTION]\n> Protocol not initialized. Call Init first.\n\n"
		return out
	}
	out += ufmt.Sprintf("- Launches: **%d**\n", launches.Size())
	if protocolAddr.IsValid() {
		out += ufmt.Sprintf("- Protocol treasury: `%s`\n", protocolAddr.String())
	}
	out += ufmt.Sprintf("- Protocol fees pending (claim/push): **%d** ugnot\n", protocolFees)
	out += ufmt.Sprintf("- Protocol fees paid (lifetime): **%d** ugnot\n\n", protocolFeesPaid)
	out += "## Markets\n\n"
	if launches.Size() == 0 {
		out += "_No launches yet. Call Create with name, symbol, uri and bond._\n"
		return out
	}
	launches.Iterate("", "", func(key string, value any) bool {
		l := value.(*Launch)
		st := "curve"
		if l.Status == StatusGraduated {
			st = "graduated"
		}
		out += ufmt.Sprintf("- [%s ($%s)](token/%s) - %s - raised %d ugnot - buyers %d\n",
			sanitize(l.Name), sanitize(l.Symbol), l.ID, st, l.RaisedUgnot, l.BuyerCount)
		return false
	})
	out += "\n[Help](help)\n"
	return out
}

func renderToken(id string) string {
	id = sanitize(id)
	l, ok := launches.Get(id).(*Launch)
	if !ok {
		return "> [!WARNING]\n> Unknown launch " + id + "\n\n[Home](./)\n"
	}
	st := "bonding curve"
	if l.Status == StatusGraduated {
		st = "graduated pool (LP locked)"
	}
	out := ufmt.Sprintf("# %s ($%s)\n\n", sanitize(l.Name), sanitize(l.Symbol))
	out += ufmt.Sprintf("- **ID:** %s\n", l.ID)
	out += ufmt.Sprintf("- **Status:** %s\n", st)
	out += ufmt.Sprintf("- **Creator:** %s\n", l.Creator.String())
	if l.URI != "" {
		out += ufmt.Sprintf("- **URI:** %s\n", sanitize(l.URI))
	}
	out += ufmt.Sprintf("- **Unique buyers:** %d\n", l.BuyerCount)
	out += ufmt.Sprintf("- **Creator fees (claimable):** %d ugnot\n\n", l.CreatorFees)

	if l.Status == StatusCurve {
		remaining := CurveSupply - l.RealSold
		pct := int64(0)
		if GraduationThreshold > 0 {
			pct = l.RaisedUgnot * 100 / GraduationThreshold
			if pct > 100 {
				pct = 100
			}
		}
		spot := ammmath.SpotPriceUgnotPerToken(l.VirtualUgnot, l.VirtualToken)
		out += "## Bonding curve\n\n"
		out += ufmt.Sprintf("- Raised: **%d** / %d ugnot (%d%%)\n", l.RaisedUgnot, GraduationThreshold, pct)
		out += ufmt.Sprintf("- Tokens sold: **%d** / %d\n", l.RealSold, CurveSupply)
		out += ufmt.Sprintf("- Remaining on curve: **%d**\n", remaining)
		out += ufmt.Sprintf("- Spot (ugnot/token x1e6): **%d**\n", spot)
		out += "\nProgress toward graduation:\n\n"
		out += progressBar(pct) + "\n"
	} else {
		spot := ammmath.SpotPriceUgnotPerToken(l.PoolUgnot, l.PoolToken)
		out += "## Liquidity (post-graduate)\n\n"
		out += ufmt.Sprintf("- Raised capital (record): **%d** ugnot\n", l.PoolUgnot)
		out += ufmt.Sprintf("- Remaining tokens seeded: **%d**\n", l.PoolToken)
		out += ufmt.Sprintf("- Spot (ugnot/token x1e6): **%d**\n", spot)
		if l.GnoswapListed {
			out += ufmt.Sprintf("- **Gnoswap listed:** `%s`\n", sanitize(l.GnoswapPoolPath))
			out += ufmt.Sprintf("- Position NFT id: **%d** (pad-owned, locked)\n", l.GnoswapPositionID)
			out += ufmt.Sprintf("- Fee WUGNOT spent: **%d** | LP WUGNOT: **%d**\n", l.FeeWugnotSpent, l.LiqWugnotUsed)
			out += "\n> [!NOTE]\n> Trade on Gnoswap router - pad SwapBuy/SwapSell disabled after auto-list.\n"
		} else {
			out += ufmt.Sprintf("- Gnoswap: %s\n", sanitize(l.GnoswapNote))
			out += "\n> [!NOTE]\n> Internal CPMM. List: wugnot.Deposit -> Approve(pad) -> RetryListGnoswap (LP ugnot reimbursed; prefer GNS for fee).\n"
			out += ufmt.Sprintf("- ListNeed: `%s`\n", listNeedOf(l))
		}
	}

	out += "\n## Trade\n\n"
	out += "Use wallet MsgCall (payable txs):\n\n"
	if l.Status == StatusCurve {
		out += ufmt.Sprintf("- Buy(id) with -send ugnot - id=%s\n", l.ID)
		out += "- Sell(id, tokensIn)\n"
		out += "- Graduate(id) when threshold met\n"
	} else if l.GnoswapListed {
		out += "- Trade on Gnoswap router (pad SwapBuy/Sell disabled)\n"
		out += ufmt.Sprintf("- Pool: `%s`\n", sanitize(l.GnoswapPoolPath))
	} else {
		out += "- SwapBuy(id) with -send ugnot\n"
		out += "- SwapSell(id, tokensIn)\n"
		out += ufmt.Sprintf("- RetryListGnoswap(id) - auto-pull WUGNOT/GNS from caller if Approved - id=%s\n", l.ID)
	}
	out += "\n[Home](./) | [Help](help)\n"
	return out
}

func progressBar(pct int64) string {
	if pct < 0 {
		pct = 0
	}
	if pct > 100 {
		pct = 100
	}
	filled := int(pct / 5)
	bar := "["
	for i := 0; i < 20; i++ {
		if i < filled {
			bar += "#"
		} else {
			bar += "."
		}
	}
	bar += "] " + strconv.FormatInt(pct, 10) + "%"
	return bar
}

